// Parses the model's JSON reply. Accepts either shape:
//   Gemini  -> { content: { parts: [{ text: "<json string>" }] } }
//   OpenAI  -> { output: [ { content: [{ text: <already-parsed object> }] } ] }
// so the node keeps working whichever branch produced the item.

function collectParts(json) {
  const out = [];
  const add = (v) => {
    if (v === undefined || v === null || v === '') return;
    out.push(v);
  };

  // Gemini, "Simplify Output" on (the candidate itself)
  for (const p of json?.content?.parts ?? []) add(p?.text);

  // Gemini, "Simplify Output" off (full response)
  if (!out.length) {
    for (const c of json?.candidates ?? []) {
      for (const p of c?.content?.parts ?? []) add(p?.text);
    }
  }

  // OpenAI Responses API, simplified or raw
  if (!out.length) {
    for (const m of json?.output ?? []) {
      for (const c of m?.content ?? []) add(c?.text);
    }
  }

  // Last resorts
  if (!out.length) add(json?.output_text);
  if (!out.length) add(json?.message?.content);
  if (!out.length) add(json?.text);
  if (!out.length && typeof json?.content === 'string') add(json.content);

  return out;
}

const results = [];

for (const item of $input.all()) {
  const json = item.json ?? {};

  // Both models failed: the item still carries the upstream error.
  if (json.error && json.script === undefined) {
    results.push({ json: { error: 'model_failed', detail: String(json.error) } });
    continue;
  }

  const parts = collectParts(json);

  // In JSON mode the OpenAI node hands back an object, not a string.
  const asObject = parts.find((p) => p && typeof p === 'object');
  if (asObject) {
    results.push({ json: asObject });
    continue;
  }

  let raw = parts.filter((p) => typeof p === 'string').join('').trim();
  raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

  let parsed = null;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    // Some replies wrap the JSON in a sentence - take the outermost braces.
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    if (start !== -1 && end > start) {
      try {
        parsed = JSON.parse(raw.slice(start, end + 1));
      } catch (e2) {}
    }
  }

  if (parsed && typeof parsed === 'object') {
    results.push({ json: parsed });
  } else {
    results.push({ json: { error: 'parse_failed', raw } });
  }
}

return results;

