// Build Merged Context: combine body text, caption, OCR text and image summary
// from the image branch, and expose image-analysis fields for the editor.
const ctx = $('SRC - Has Content').first().json || {};
let paths = ctx.media_local_paths;
if (typeof paths === 'string') { try { paths = JSON.parse(paths); } catch (e) { paths = []; } }
if (!Array.isArray(paths)) paths = [];

// Vision node output (OpenRouter chat/completions). On failure the fields are absent.
const vj = $json || {};
let analysis = null;
try {
  const content = vj.choices && vj.choices[0] && vj.choices[0].message && vj.choices[0].message.content;
  if (content) analysis = JSON.parse(content);
} catch (e) { analysis = null; }

const ocrText = analysis && typeof analysis.ocr_text === 'string' ? analysis.ocr_text : '';
const ocrStatus = analysis ? 'ok' : 'unavailable';
const imageSummary = analysis && analysis.image_summary ? analysis.image_summary : '';
const imageKind = analysis && analysis.image_kind ? analysis.image_kind : 'unknown';
const sensitive = analysis ? !!analysis.sensitive : false;
const recVs = analysis && analysis.recommended_visual_strategy ? analysis.recommended_visual_strategy : '';

const parts = [];
if ((ctx.text || '').trim()) parts.push('النص:\n' + ctx.text.trim());
if ((ctx.caption || '').trim()) parts.push('التعليق:\n' + ctx.caption.trim());
if (ocrText.trim()) parts.push('[نص داخل الصورة / OCR]\n' + ocrText.trim());
if (imageSummary.trim()) parts.push('[وصف الصورة]\n' + imageSummary.trim());
let merged = parts.join('\n\n');
if (!merged.trim()) merged = (ctx.caption || ctx.text || '').trim();

return [{ json: {
  text: merged,
  source_type: ctx.source_type || 'telegram',
  article_url: ctx.article_url || ctx.source_url || '',
  source_image_url: ctx.source_image_url || '',
  publisher: ctx.publisher || '',
  display_url: ctx.display_url || '',
  source_name: ctx.source_name || '',
  source_url: ctx.source_url || '',
  caption: ctx.caption || '',
  message_id: ctx.message_id ?? '',
  preview_channel_name: ctx.preview_channel_name || ctx.channel || '',
  has_media: true,
  source_has_image: true,
  source_media_type: ctx.media_type || 'photo',
  media_type: ctx.media_type || 'photo',
  media_count: Number(ctx.media_count || 0),
  media_group_id: ctx.media_group_id || '',
  media_local_paths: paths,
  image_first_ref: paths[0] || '',
  ocr_text: ocrText,
  ocr_status: ocrStatus,
  image_summary: imageSummary,
  image_kind: imageKind,
  sensitive: sensitive,
  recommended_visual_strategy: recVs
} }];

// Attach Visual Fields: clamp visual_strategy to the allowed set and carry
// image-review context (OCR, kind, refs) onto the validated editorial item
// so later phases can show a source preview + OCR snippet + strategy.
const ALLOWED = ['source','recreate','news_card','manual_review'];
let img = null;
try { img = $('MEDIA - Merge Image Context').first().json; } catch (e) { img = null; }
const out = [];
for (const item of $input.all()) {
  const j = Object.assign({}, item.json);
  const hasImg = (j.source_has_image === true) || (img != null);
  j.source_has_image = !!hasImg;
  j.source_media_type = j.source_media_type || (img ? img.source_media_type : 'none') || 'none';
  let vs = j.visual_strategy;
  if (!ALLOWED.includes(vs)) vs = j.source_has_image ? 'manual_review' : 'news_card';
  j.visual_strategy = vs;
  if (img) {
    j.ocr_text = img.ocr_text || '';
    j.ocr_status = img.ocr_status || 'ok';
    j.image_summary = img.image_summary || '';
    j.image_kind = img.image_kind || 'unknown';
