    '⚠️ *فشل توليد الصورة* — ' + esc(String(E.title || '').slice(0, 120)),
    '🎯 ' + esc(E.visual_strategy) + ' | محاولة ' + attempt + '/' + maxA + ' | ❗ ' + esc(String(E.generation_error || '').slice(0, 160)),
    '',
    'اختر الإجراء النهائي:',
    hasSource ? 'الصورة الأصلية ما زالت متاحة: يمكنك نشر الخبر بها، أو توليد صورة ثانية، أو إلغاء الخبر.' : 'لا توجد صورة أصلية لهذا الخبر، لذلك يمكنك إعادة توليد الصورة أو إلغاء الخبر.',
  ].concat(opts).concat([
    '',
    '⚠️ اختيار "نشر" سيرسل الخبر فعلياً إلى Postiz ثم Facebook وTelegram.',
    '👇 اضغط الزر أدناه لفتح نموذج الاختيار.'
  ]).join('\n');
} else {
  message = [
    '🖼 *مراجعة الصورة* — ' + esc(String(E.title || '').slice(0, 120)),
    '🎯 ' + esc(E.visual_strategy) + ' | محاولة ' + attempt + '/' + maxA + ' | 🤖 ' + esc(E.generated_image_model) + ' | 💰 ' + cost + ' (total ' + total + ')',
    '',
    'تم تجهيز الصورة البديلة.',
    '',
    'اختر الإجراء النهائي:',
    hasSource ? 'يمكنك نشر الخبر بالصورة الأصلية أو بالصورة المولدة (صورة توضيحية)، أو توليد صورة ثانية، أو إلغاء الخبر.' : 'لا توجد صورة أصلية لهذا الخبر، لذلك يمكنك نشر الصورة المولدة أو إعادة توليدها.',
  ].concat(opts).concat([
    '',
    '⚠️ اختيار "نشر" سيرسل الخبر فعلياً إلى Postiz ثم Facebook وTelegram.',
    '👇 اضغط الزر أدناه لفتح نموذج الاختيار.'
  ]).join('\n');
}
const formDescription = '⚠️ اختيار أحد خياري النشر سيُرسل الخبر فعلياً إلى Postiz ثم Facebook وTelegram. | ' + String(E.title || '').slice(0, 150) + ' | attempt ' + attempt + '/' + maxA + (E.generation_failed ? ' | generation FAILED' : '');
return [{ json: Object.assign(E, { visual_review_message: message, visual_review_form_description: formDescription, visual_review_round: $runIndex + 1, has_source_image: hasSource, review_variant: variant }) }];

// V3: Parse Visual Decision
// Normalises the review form answer into one of: use_generated, use_original,
// regenerate, reject; anything else (timeout, stale/invalid response) or a
// regeneration past the limit is routed to manual review. Never publishes.
const j = $json || {};
let E = {};
try { E = Object.assign({}, $('VREVIEW - Prepare Review').first(0).json); } catch (e) { E = {}; }
delete E.generated_image_b64;
delete E.image_request_body;
const d = (j.data && typeof j.data === 'object') ? j.data : null;
let raw = '';
if (d) {
  for (const v of Object.values(d)) { if (typeof v === 'string' && /Use generated|Use original|Regenerate|Retry|Reject|بالصورة المولدة|بالصورة الأصلية|توليد صورة|إعادة المحاولة|إلغاء الخبر/i.test(v)) { raw = v; break; } }
  if (!raw && typeof d['القرار'] === 'string') raw = d['القرار'];
}
let decision;
if (!d) decision = 'timeout';
else if (/use generated|بالصورة المولدة/i.test(raw)) decision = 'use_generated';
else if (/use original|بالصورة الأصلية/i.test(raw)) decision = 'use_original';
else if (/regenerate|retry|توليد صورة|إعادة المحاولة/i.test(raw)) decision = 'regenerate';
else if (/reject|إلغاء الخبر/i.test(raw)) decision = 'reject';
else decision = 'invalid';
const maxAttempts = Number(E.max_generation_attempts || 3);
const attempt = Number(E.image_generation_attempt || 0);
const reviewRound = $runIndex + 1;
let route = decision;
let note = '';
if (decision === 'use_generated' && (E.generation_failed === true || !E.generated_image_media_type)) { route = 'manual_review'; note = '"use generated" chosen but no generated image exists'; }
if (decision === 'regenerate' && (attempt >= maxAttempts || reviewRound >= maxAttempts)) { route = 'manual_review'; note = 'regeneration limit reached (' + attempt + '/' + maxAttempts + ' generations, ' + (maxAttempts - 1) + ' regenerations max)'; }
if (decision === 'timeout') { route = 'manual_review'; note = 'visual review timed out without a decision'; }
if (decision === 'invalid') { route = 'manual_review'; note = 'unrecognised review response: ' + String(raw).slice(0, 60); }
if (decision === 'use_original' && String(E.source_media_type) !== 'photo') { note = '"use original" chosen but the source has no photo; publishing text only'; }
const idx = { use_generated: 0, use_original: 1, regenerate: 2, reject: 3, manual_review: 4 }[route];
const selected = route === 'use_generated' ? 'generated' : (route === 'use_original' ? (String(E.source_media_type) === 'photo' ? 'source' : 'none') : (route === 'reject' ? 'none' : 'pending'));
return [{ json: Object.assign(E, {
  visual_decision_raw: raw,
  visual_decision: decision,
  visual_route: route,
  visual_route_index: idx,
  visual_route_note: note,
  selected_visual: selected,
  visual_reviewed_at: (d && d.respondedAt) || '',
  visual_review_round: reviewRound
}) }];

// V3: Restore For Publish
// Hands the approved editorial item, plus the visual decision, to the existing
// publishing chain unchanged. Postiz still publishes text only in V3; the
// generated image never reaches it automatically (selected_visual is recorded
// for the next phase).
const j = Object.assign({}, $json);
delete j.generated_image_b64;
delete j.image_request_body;
delete j.visual_review_message;
j.v3_visual_stage = 'complete';
return [{ json: j }];

