// V4: Load Overlay Badge
// Attaches the pre-rendered "صورة توضيحية" label (PNG with alpha, 242x60,
// rendered once with proper Arabic shaping) as binary "overlay_badge" and
// computes a fixed lower-right position from the validated image size.
// Only generated visuals pass through here; source images are never touched.
const BADGE_B64 = '';
const BADGE_W = 242, BADGE_H = 60, MARGIN = 24;
let V = {};
try { V = $('GEN - Validate Generated Image').first(0).json || {}; } catch (e) { V = {}; }
const item = $input.first();
const binary = Object.assign({}, item.binary || {});
if (!binary.generated_image) throw new Error('generated_image binary missing before overlay');
const w = Number(V.generated_image_width) || 0;
const h = Number(V.generated_image_height) || 0;
let x = MARGIN, y = MARGIN, fallback = true;
if (w >= BADGE_W + 2 * MARGIN && h >= BADGE_H + 2 * MARGIN) { x = w - BADGE_W - MARGIN; y = h - BADGE_H - MARGIN; fallback = false; }
binary.overlay_badge = { data: BADGE_B64, mimeType: 'image/png', fileName: 'overlay_badge.png', fileExtension: 'png' };
return [{ json: { overlay_x: x, overlay_y: y, overlay_position_fallback: fallback, overlay_text: 'صورة توضيحية', overlay_badge_size: BADGE_W + 'x' + BADGE_H, base_width: w, base_height: h, generated_image_file_name: V.generated_image_file_name || 'generated.png' }, binary }];

// V4: Select Visual
// Turns the human review decision into ONE canonical selected visual.
// use_generated -> "generated" (image WITH the illustrative overlay)
// use_original  -> "source" (the original photo exactly as received)
const j = Object.assign({}, $json);
delete j.generated_image_b64;
delete j.image_request_body;
const route = String(j.visual_route || '');
let selected = 'none';
let ok = false;
let note = '';
if (route === 'use_generated') {
  if (j.generation_failed === true || !j.generated_image_media_type) note = 'use generated chosen but no generated image exists';
  else { selected = 'generated'; ok = true; }
} else if (route === 'use_original') {
  if (String(j.source_media_type) !== 'photo') note = 'use original chosen but the source has no photo';
  else { selected = 'source'; ok = true; }
} else note = 'unexpected visual route ' + route;
const origin = selected === 'generated' ? ('openrouter ' + String(j.generated_image_model || '') + ' + illustrative overlay') : (selected === 'source' ? 'telegram source photo (unmodified)' : '');
return [{ json: Object.assign(j, { selected_visual: selected, selection_ok: ok, selection_note: note, visual_route_note: note || j.visual_route_note || '', selected_visual_origin: origin, postiz_publish_started: false, postiz_publish_completed: false }) }];

// V4: Prepare Selected Image
// Attaches exactly ONE binary, "selected_visual", for the Postiz upload.
// Source images are attached as received (no overlay, no edit). Generated
// images are taken from the overlay node's latest run (the newest candidate).
const j = Object.assign({}, $json);
let src = null;
if (j.selected_visual === 'generated') {
  try { src = $('GEN - Apply Overlay (صورة توضيحية)').first(0).binary.generated_image; } catch (e) { src = null; }
  if (!src) throw new Error('generated image binary with overlay not found');
} else if (j.selected_visual === 'source') {
  try { src = $('MEDIA - Prepare Source Image').first(0).binary.image0; } catch (e) { src = null; }
  if (!src) throw new Error('original source image binary not found');
} else throw new Error('no visual selected');
const mime = String(src.mimeType || (j.selected_visual === 'generated' ? 'image/png' : 'image/jpeg'));
const ext = mime === 'image/png' ? 'png' : (mime === 'image/webp' ? 'webp' : 'jpg');
const base = 'salamtak_' + (j.message_id || 'item');
const fileName = j.selected_visual === 'generated' ? (base + '_generated_a' + (j.image_generation_attempt || 1) + '_illustrative.' + ext) : (base + '_source.' + ext);
const binary = { selected_visual: Object.assign({}, src, { fileName: fileName }) };
return [{ json: Object.assign(j, { selected_visual_binary_property: 'selected_visual', selected_visual_media_type: mime, selected_visual_filename: fileName, selected_visual_file_size: src.fileSize || '', selected_visual_binary_id: src.id || '' }), binary }];

// V4: Build Postiz Media
// Validates the Postiz upload response and prepares the post media object
// ([{ id, path }], the shape required by Postiz MediaDto). Marks the durable
// publish state as started; completion is marked only after both posts succeed.
const resp = $json || {};
let E = {};
try { E = Object.assign({}, $('PUB - Prepare Selected Image').first(0).json); } catch (e) { E = {}; }
const fail = (m) => { throw new Error('postiz upload response invalid - ' + String(m).replace(/:/g, ' -')); };
const cand = (resp && typeof resp === 'object') ? ((resp.data && typeof resp.data === 'object' && resp.data.id) ? resp.data : resp) : null;
if (!cand) fail('empty response');
const id = String(cand.id || '').trim();
const path = String(cand.path || '').trim();
if (!id) fail('media id missing');
if (!path) fail('media path missing');
if (!/^(https?:\/\/|\/)/i.test(path)) fail('media path is not a URL');
if (!/\.(png|jpe?g|webp|gif)(\?|$)/i.test(path)) fail('media path has no image extension');
const now = new Date().toISOString();
return [{ json: Object.assign(E, { postiz_media: [{ id: id, path: path }], postiz_media_id: id, postiz_media_path: path, postiz_media_uploaded_at: now, postiz_publish_started: true, postiz_publish_started_at: now, postiz_publish_completed: false }) }];

// V4: Mark Publish Completed
// Reached only after BOTH Postiz calls succeeded; records the durable state.
let E = {};
try { E = Object.assign({}, $('PUB - Restore Article').first(0).json); } catch (e) { E = {}; }
let fb = null;
try { fb = $('PUB - Publish Facebook').first(0).json; } catch (e) { fb = null; }
const tg = $json || {};
const pick = (r) => { if (!r || typeof r !== 'object') return null; const arr = Array.isArray(r) ? r : (Array.isArray(r.posts) ? r.posts : [r]); return arr.map(p => p && (p.postId || p.id || p.releaseId || null)).filter(Boolean); };
delete E.generated_image_b64;
delete E.image_request_body;
return [{ json: Object.assign(E, { postiz_publish_completed: true, postiz_publish_completed_at: new Date().toISOString(), postiz_facebook_result: pick(fb), postiz_telegram_result: pick(tg) }) }];

// WEB - Source List
// Configuration of website / RSS sources. Add a source by adding one object.
//   name: display name        type: 'rss'        url: feed URL
//   fetch_page: fetch the article page for og:image / full text when the feed is thin (default true)
//   title_publisher_suffix: feed titles end with " - Publisher" (Google News style)
const SOURCES = [
  { name: 'Google News Iraq', type: 'rss', url: 'https://news.google.com/rss/search?q=%D8%A7%D9%84%D8%B9%D8%B1%D8%A7%D9%82&hl=ar&gl=IQ&ceid=IQ:ar', fetch_page: false, title_publisher_suffix: true },
  { name: 'Al Mada', type: 'rss', url: 'https://almadapaper.net/feed', fetch_page: true, title_publisher_suffix: false },
];
// [SOURCES-END]
return SOURCES.filter(s => s && s.type === 'rss' && /^https?:\/\//i.test(String(s.url))).map(s => ({ json: s }));

// WEB - Normalize Article
// Converts RSS items from every source into the common article object used by
// the Telegram path. Image priority: enclosure > media:content > media:thumbnail
// > media:group > first <img> in content. Page fetch is decided here, done later.
const CFG = { MAX_AGE_HOURS: 36, MIN_TEXT_CHARS: 400 };
let srcList = [];
try { srcList = $('WEB - Source List').all().map(i => i.json); } catch (e) { srcList = []; }
const decode = (s) => String(s || '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&#(\d+);/g, (m, d) => String.fromCharCode(Number(d)));
const strip = (h) => decode(String(h || '').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|li|h[1-6]|tr)>/gi, '\n').replace(/<[^>]+>/g, ' ')).replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const normUrl = (u) => { try { const x = new URL(String(u).trim()); x.hash = ''; for (const k of [...x.searchParams.keys()]) if (/^(utm_|fbclid|gclid|ref$)/i.test(k)) x.searchParams.delete(k); x.hostname = x.hostname.toLowerCase(); return x.toString(); } catch (e) { return String(u || '').trim(); } };
const attr = (m) => (m && typeof m === 'object') ? (m.$ || m) : {};
const firstImg = (html) => { const m = String(html || '').match(/<img[^>]+src=["']([^"']+)["']/i); return m ? m[1] : ''; };
const pickMedia = (it) => {
  const c = [];
  if (it.enclosure && it.enclosure.url && (!it.enclosure.type || /^image\//i.test(it.enclosure.type))) c.push(['rss_enclosure', it.enclosure.url]);
  for (const key of ['media:content', 'media:thumbnail']) { const v = it[key]; for (const m of (Array.isArray(v) ? v : (v ? [v] : []))) { const a = attr(m); const url = a.url || (typeof m === 'string' ? m : ''); if (url && (!a.medium || a.medium === 'image') && (!a.type || /^image\//i.test(a.type))) c.push([key.replace(':', '_'), url]); } }
  const g = it['media:group']; if (g && g['media:content']) { for (const m of (Array.isArray(g['media:content']) ? g['media:content'] : [g['media:content']])) { const a = attr(m); if (a.url) c.push(['media_group', a.url]); } }
  const ci = firstImg(it['content:encoded'] || it.content); if (ci) c.push(['content_img', ci]);
  return c.find(x => /^https?:\/\//i.test(x[1])) || null;
};
const now = Date.now(); const out = [];
for (const item of $input.all()) {
  const it = item.json || {};
  const pi = item.pairedItem; const idx = Array.isArray(pi) ? (pi[0] && pi[0].item) : (pi && typeof pi === 'object' ? pi.item : pi);
  const src = srcList[Number(idx)] || srcList[0] || {};
  const link = normUrl(it.link || it.guid || ''); if (!link) continue;
  let title = strip(it.title); let publisher = src.name || '';
  if (src.title_publisher_suffix) { const m = title.match(/^(.*)\s[-–]\s([^-–]{2,60})$/); if (m) { title = m[1].trim(); publisher = m[2].trim(); } }
  const body = strip(it['content:encoded'] || it.content || it.description || it.contentSnippet || it.summary || '');
  const dateIso = it.isoDate || it.pubDate || ''; const ts = Date.parse(dateIso);
  if (!isNaN(ts) && now - ts > CFG.MAX_AGE_HOURS * 3600e3) continue;
  const media = pickMedia(it);
  let host = ''; try { host = new URL(link).origin; } catch (e) { host = ''; }
  out.push({ json: {
    source_type: 'website', source_name: src.name || 'website', source_url: link, article_url: link, article_id: link, dedupe_key: link,
    publisher, display_url: link.length > 90 ? (host + '/…') : link,
    title, text: (title + '\n\n' + body).trim(), date: dateIso, caption: '', channel: '', message_id: '',
    has_media: !!media, media_type: media ? 'photo' : 'none', media_count: media ? 1 : 0, media_group_id: '',
    media_local_paths: media ? JSON.stringify([media[1]]) : '[]', source_image_url: media ? media[1] : '', source_image_origin: media ? media[0] : '',
    source_has_image: !!media, source_media_type: media ? 'photo' : 'none', preview_channel_name: src.name || '',
    body_chars: body.length, needs_page_fetch: src.fetch_page !== false && (!media || body.length < CFG.MIN_TEXT_CHARS), _ts: isNaN(ts) ? 0 : ts,
  } });
}
out.sort((a, b) => b.json._ts - a.json._ts);
return out;

// WEB - Dedupe & Limit
// Website duplicates are rejected by the normalized article URL (dedupe_key),
// remembered in workflow static data. Only the newest UNSEEN articles are
// released (MAX_ITEMS_PER_RUN, kept at 1 so every execution handles one article,
// which is what the review and publishing stages expect). Only released items
// are marked as seen, so skipped articles are picked up by later runs.
const CFG = { MAX_ITEMS_PER_RUN: 1, HISTORY_SIZE: 5000 };
const store = $getWorkflowStaticData('global');
if (!store.web_seen || typeof store.web_seen !== 'object') store.web_seen = {};
const seen = store.web_seen; const out = [];
for (const item of $input.all()) {
  const key = String(item.json.dedupe_key || item.json.article_url || '').trim(); if (!key) continue;
  if (seen[key]) continue;
  if (out.length >= CFG.MAX_ITEMS_PER_RUN) break;
  seen[key] = Date.now(); const j = Object.assign({}, item.json); delete j._ts; out.push({ json: j });
}
const keys = Object.keys(seen); if (keys.length > CFG.HISTORY_SIZE) { keys.sort((a, b) => seen[a] - seen[b]); for (const k of keys.slice(0, keys.length - CFG.HISTORY_SIZE)) delete seen[k]; }
return out;

// WEB - Parse Page
// Extracts og:image and readable article text from the fetched page (no
// navigation, scripts, ads or boilerplate). Never bypasses access controls:
// on any fetch error the feed content is kept and the AI decides publishability.
const bases = $('WEB - Need Page Fetch?').all(0);
const decode = (s) => String(s || '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&#(\d+);/g, (m, d) => String.fromCharCode(Number(d)));
const out = [];
$input.all().forEach((item, i) => {
  const pi = item.pairedItem; const idx = Array.isArray(pi) ? (pi[0] && pi[0].item) : (pi && typeof pi === 'object' ? pi.item : (pi == null ? i : pi));
  const base = Object.assign({}, (bases[Number(idx)] || bases[i] || { json: {} }).json);
  const html = typeof item.json.html === 'string' ? item.json.html : '';
  let status = html ? 'ok' : ('failed: ' + String((item.json.error && (item.json.error.message || item.json.error)) || 'empty response').slice(0, 120));
  let og = '';
  if (html) { const m = html.match(/<meta[^>]+(?:property|name)=["'](?:og:image|og:image:url|twitter:image)["'][^>]*content=["']([^"']+)["']/i) || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]*(?:property|name)=["'](?:og:image|og:image:url|twitter:image)["']/i); if (m) og = decode(m[1]); }
  let text = '';
  if (html) {
    let h = html.replace(/<(script|style|noscript|nav|header|footer|aside|form|iframe|svg|figure)[\s\S]*?<\/\1>/gi, ' ').replace(/<!--[\s\S]*?-->/g, ' ');
    const art = h.match(/<article[\s\S]*?<\/article>/i); if (art) h = art[0];
    const paras = []; const re = /<p\b[^>]*>([\s\S]*?)<\/p>/gi; let m;
    while ((m = re.exec(h)) !== null) { const t = decode(m[1].replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim(); if (t.length >= 40 && !/cookie|subscribe|all rights reserved|جميع الحقوق/i.test(t)) paras.push(t); }
    text = paras.join('\n').slice(0, 6000);
  }
  const j = Object.assign(base, { page_fetch_status: status, page_text_chars: text.length });
  if (text.length > 300 && text.length > Number(base.body_chars || 0)) { j.text = (String(base.title || '') + '\n\n' + text).trim(); j.text_source = 'page'; } else j.text_source = 'feed';
  if (!j.source_image_url && og && /^https?:\/\//i.test(og)) { j.source_image_url = og; j.source_image_origin = 'og_image'; j.has_media = true; j.media_type = 'photo'; j.media_count = 1; j.media_local_paths = JSON.stringify([og]); j.source_has_image = true; j.source_media_type = 'photo'; }
  out.push({ json: j });
});
return out;

// WEB - Finalize Media
// Keeps the downloaded image as binary "image0" (same format the Telegram path
// uses) when it really is an image; otherwise the article continues text-only.
const bases = $('WEB - Has Image URL?').all(0);
const out = [];
$input.all().forEach((item, i) => {
  const pi = item.pairedItem; const idx = Array.isArray(pi) ? (pi[0] && pi[0].item) : (pi && typeof pi === 'object' ? pi.item : (pi == null ? i : pi));
  const j = Object.assign({}, (bases[Number(idx)] || bases[i] || { json: {} }).json);
  const b = item.binary && item.binary.image0; const mime = b ? String(b.mimeType || '') : '';
  const ok = !!b && /^image\/(jpeg|jpg|png|webp)/i.test(mime);
  if (ok) { const ext = /png/i.test(mime) ? 'png' : (/webp/i.test(mime) ? 'webp' : 'jpg'); const bin = Object.assign({}, b, { fileName: 'web_' + Date.now() + '.' + ext }); j.image_download_status = 'ok'; out.push({ json: j, binary: { image0: bin } }); }
